const today = new Date();
today.setHours(0, 0, 0, 0);

const validItems = $input.all().filter(item => {
  const rowData = item.json;

  const linkBlog = rowData['Link do Blog'];
  if (!linkBlog || linkBlog.trim() === '') return false;

  const dateString = rowData['Data de Publicação'];
  if (!dateString) return false;

  const parts = dateString.split('/');
  const rowDate = new Date(parts[2], parts[1] - 1, parts[0]);
  rowDate.setHours(0, 0, 0, 0);

  return rowDate <= today;
});

if (validItems.length === 0) {
  return [];
}

validItems.sort((a, b) => {
  const dateA = a.json['Data de Publicação'].split('/').reverse().join('');
  const dateB = b.json['Data de Publicação'].split('/').reverse().join('');
  return dateA.localeCompare(dateB);
});

return [validItems[0]];

const html = $input.first().json.html;
const linha = $('Prepara o tema LinkedIn').first().json; // fonte única da verdade

let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    conteudo_artigo: text.substring(0, 8000),
    link_blog: linha['Link do Blog'],
    tema: linha['Tema'],
    data_publicacao: linha['Data de Publicação'],
    row_number: linha.row_number
  }
}];

const resposta = $input.first()?.json;

if (!resposta) {
  throw new Error('Nenhum item chegou ao node. O Gerar Post LinkedIn com IA não devolveu dados.');
}

const finish = resposta?.candidates?.[0]?.finishReason;
const rawText = resposta?.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error(
    'Gemini não devolveu texto. finishReason=' + finish +
    ' | payload: ' + JSON.stringify(resposta).substring(0, 500)
  );
}

const str = String(rawText).replace(/```json/gi, '').replace(/```/g, '').trim();

let linkedin_post_text;
try {
  linkedin_post_text = JSON.parse(str).linkedin_post_text;
} catch (e) {
  const match = str.match(/"linkedin_post_text"\s*:\s*"([\s\S]*?)"\s*\}/);
  if (!match) {
    throw new Error('JSON inválido ou truncado (finishReason=' + finish + '): ' + str.substring(0, 400));
  }
  linkedin_post_text = match[1]
    .replace(/\\n/g, '\n')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\');
}

if (!linkedin_post_text || linkedin_post_text.trim() === '') {
  throw new Error('O post veio vazio. finishReason=' + finish);
}

console.log('Post gerado com ' + linkedin_post_text.length + ' caracteres.');

return [{ json: { linkedin_post_text } }];

