const texto = $('Prepara Post Revisado').first().json.linkedin_post_text || '(sem texto)';
const rowNumber = String($('Extrai texto do HTML').first().json.row_number);
const linkBlog = $('Extrai texto do HTML').first().json.link_blog;
const imagemUrl = 'https://drive.google.com/uc?export=view&id=' + $('Upload file').first().json.id;

const blocks = [
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text: "<@SEU_USER_ID_SLACK> *📝 Novo post LinkedIn para aprovação:*\n\n" + texto
    }
  }
];

if (imagemUrl) {
  blocks.push({
    type: "image",
    image_url: imagemUrl,
    alt_text: "Imagem gerada para o post"
  });
}

blocks.push({
  type: "actions",
  elements: [
    {
      type: "button",
      action_id: "approve_post",
      text: { type: "plain_text", text: "✅ Aprovar e Publicar" },
      style: "primary",
      value: "approve__" + rowNumber + "__" + linkBlog
    },
    {
      type: "button",
      action_id: "reject_post",
      text: { type: "plain_text", text: "❌ Reprovar" },
      style: "danger",
      value: "reject__" + rowNumber + "__" + linkBlog
    }
  ]
});

return [{
  json: {
    channel: "SEU_CHANNEL_ID_SLACK",
    text: "Novo post LinkedIn para aprovação",
    blocks: blocks
  }
}];

